def blip(program):
    import re
    tokens = program.split(" ") if program else []
    match, open_stack = {}, []
    for i, tok in enumerate(tokens):
        if tok == "[":
            open_stack.append(i)
        elif tok == "]":
            if not open_stack:
                return "ERROR"
            match[open_stack.pop()] = i
    if open_stack:
        return "ERROR"
    stack, out = [], []

    class Bad(Exception):
        pass

    def pop():
        if not stack:
            raise Bad()
        return stack.pop()

    def run(lo, hi):
        i = lo
        while i < hi:
            tok = tokens[i]
            if re.fullmatch(r"-?[0-9]+", tok):
                stack.append(int(tok))
            elif tok in ("+", "-", "*", "/"):
                b = pop()
                a = pop()
                if tok == "+":
                    stack.append(a + b)
                elif tok == "-":
                    stack.append(a - b)
                elif tok == "*":
                    stack.append(a * b)
                else:
                    if b == 0:
                        raise Bad()
                    stack.append(a // b)
            elif tok == "dup":
                a = pop()
                stack.extend([a, a])
            elif tok == "drop":
                pop()
            elif tok == "swap":
                b = pop()
                a = pop()
                stack.extend([b, a])
            elif tok == "over":
                if len(stack) < 2:
                    raise Bad()
                stack.append(stack[-2])
            elif tok == "print":
                out.append(pop())
            elif tok == "[":
                n = pop()
                end = match[i]
                for _ in range(max(n, 0)):
                    run(i + 1, end)
                i = end
            elif tok == "]":
                pass
            else:
                raise Bad()
            i += 1

    try:
        run(0, len(tokens))
    except Bad:
        return "ERROR"
    return out
