def kessel_date(n):
    names = ["Ao", "Bel", "Cur", "Dax", "Eph", "Fen"]
    weekday = names[(n - 1) % 6]

    def leap(y):
        return (y % 4 == 0 and y % 20 != 0) or y % 100 == 0

    year, left = 1, n
    while True:
        size = 366 if leap(year) else 365
        if left > size:
            left -= size
            year += 1
        else:
            break
    month = 1
    while True:
        days = 37 if month % 2 == 1 else 36
        if month == 10 and leap(year):
            days = 37
        if left > days:
            left -= days
            month += 1
        else:
            break
    return "%d-%d-%d %s" % (year, month, left, weekday)
