def evaluate_sheet(cells):
    import re
    result, state = {}, {}

    def value(name):
        if name not in cells:
            return 0
        if name in result:
            return result[name]
        if state.get(name) == "busy":
            return None
        state[name] = "busy"
        text = cells[name]
        if not text.startswith("="):
            answer = int(text)
        else:
            answer = 0
            for sign, term in re.findall(r"([+-]?)([A-Z][0-9]+|[0-9]+)", text[1:]):
                v = int(term) if term.isdigit() else value(term)
                if v is None or v == "#CYCLE":
                    answer = "#CYCLE"
                    break
                answer += -v if sign == "-" else v
        state[name] = "done"
        result[name] = answer
        return answer

    for name in cells:
        value(name)
    return {name: result[name] for name in cells}
