def rank_teams(matches):
    stats = {}
    for home, away, hg, ag in matches:
        for team in (home, away):
            stats.setdefault(team, [0, 0, 0])
        stats[home][1] += hg - ag
        stats[away][1] += ag - hg
        stats[home][2] += hg
        stats[away][2] += ag
        if hg > ag:
            stats[home][0] += 3
        elif ag > hg:
            stats[away][0] += 3
        else:
            stats[home][0] += 1
            stats[away][0] += 1
    groups = {}
    for team, key in stats.items():
        groups.setdefault(tuple(key), []).append(team)
    table = []
    for key in sorted(groups, reverse=True):
        group = groups[key]
        mini = {team: 0 for team in group}
        for home, away, hg, ag in matches:
            if home in mini and away in mini and home != away:
                if hg > ag:
                    mini[home] += 3
                elif ag > hg:
                    mini[away] += 3
                else:
                    mini[home] += 1
                    mini[away] += 1
        table.extend(sorted(group, key=lambda team: (-mini[team], team)))
    return table
